package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.repository.jobs.*;import java.time.*;import javax.sql.DataSource;import org.junit.jupiter.api.*;import org.springframework.jdbc.datasource.DataSourceTransactionManager;
class CollectorMemoryFactsNativeTest {
 CollectorHostMemoryNativeTest f;JdbcCollectorMemoryFacts facts;Instant now;
 DataSource source(){return new CollectorHeartbeatsNativeTest().source();}
 @BeforeEach void setup()throws Exception{f=new CollectorHostMemoryNativeTest(){@Override DataSource source(){return CollectorMemoryFactsNativeTest.this.source();}};f.setup();now=f.now;facts=new JdbcCollectorMemoryFacts(f.f.db,new DataSourceTransactionManager(f.f.db),Clock.fixed(now,ZoneOffset.UTC),192L<<20);}
 @AfterEach void cleanup(){if(f!=null)f.cleanup();}
 @Test void actualCurrentNativeNodeAndExactOriginalMemoryFrameReadWithoutWritesOrHeartbeatRefresh(){var before=f.save(f.body(now,1,256L<<20),now);var value=facts.read(f.f.node);assertNotNull(value);assertEquals(f.f.node,value.nodeId());assertEquals(1,value.nodeRevision());assertTrue(value.enabled());assertEquals(1,value.historyRevision());assertEquals(before.receivedAt(),value.receivedAt());assertEquals(now,value.readAt());assertEquals(before.input().sample().processIdentity(),value.snapshot().processIdentity());assertEquals(256L<<20,value.snapshot().rssBytes());assertEquals(192L<<20,value.expectedMaximumBytes());assertNull(f.f.jdbc.queryForObject("SELECT last_seen_at FROM collector_nodes WHERE id=?",java.sql.Timestamp.class,f.f.node));assertEquals(1,f.f.tx.execute(s->f.store.latest(f.f.node,1)).revision());}
 @Test void actualMissingHistoryAndChangedNativeRevisionAreNeverInventedAsZeroMemory(){var empty=facts.read(f.f.node);assertNotNull(empty);assertNull(empty.snapshot());assertNull(empty.receivedAt());assertEquals(0,empty.historyRevision());f.save(f.body(now,1,10),now);f.f.jdbc.update("UPDATE collector_nodes SET config_revision=2 WHERE id=?",f.f.node);var changed=facts.read(f.f.node);assertNotNull(changed);assertEquals(2,changed.nodeRevision());assertNull(changed.snapshot());assertNull(changed.receivedAt());assertEquals(1,f.f.tx.execute(s->f.store.original(f.f.node)).revision());assertNull(facts.read("fictional-missing-node"));}
 @Test void malformedCurrentPermissionsIdsCapacityOrCorruptedOriginalHistoryReturnsUnknown(){f.save(f.body(now,1,10),now);f.f.jdbc.update("UPDATE collector_nodes SET permissions_json='[]' WHERE id=?",f.f.node);assertNull(facts.read(f.f.node));f.f.jdbc.update("UPDATE collector_nodes SET permissions_json='[\"heartbeat:write\",\"heartbeat:write\"]' WHERE id=?",f.f.node);assertNull(facts.read(f.f.node));f.f.jdbc.update("UPDATE collector_nodes SET permissions_json='[\"heartbeat:write\"]',allowed_source_ids=? WHERE id=?","[\""+"x".repeat(65536)+"\"]",f.f.node);assertNull(facts.read(f.f.node));f.f.jdbc.update("UPDATE collector_nodes SET allowed_source_ids='[]' WHERE id=?",f.f.node);f.f.jdbc.update("UPDATE runtime_settings SET revision=0 WHERE setting_key=?",JdbcCollectorHostMemory.key(f.f.node));assertNull(facts.read(f.f.node));}
 @Test void nativeDisabledNodeIsExplicitAndUnsafeNodeFlagsOrFutureHistoryRemainUnknown(){f.f.jdbc.update("UPDATE collector_nodes SET enabled=0 WHERE id=?",f.f.node);var value=facts.read(f.f.node);assertNotNull(value);assertFalse(value.enabled());assertNull(value.snapshot());f.f.jdbc.update("UPDATE collector_nodes SET enabled=2 WHERE id=?",f.f.node);assertNull(facts.read(f.f.node));f.f.jdbc.update("UPDATE collector_nodes SET enabled=1 WHERE id=?",f.f.node);f.save(f.body(now.plusSeconds(1),1,10),now.plusSeconds(1));assertNull(facts.read(f.f.node));}
 @Test void ownedReadonlyRepeatableSnapshotForbidsOuterTransactionAndInvalidBudget(){assertThrows(IllegalStateException.class,()->f.f.tx.execute(s->facts.read(f.f.node)));assertThrows(RuntimeException.class,()->new JdbcCollectorMemoryFacts(f.f.db,new DataSourceTransactionManager(f.f.db),Clock.fixed(now,ZoneOffset.UTC),0));var value=facts.read(f.f.node);assertNotNull(value);assertNull(value.snapshot());assertEquals(0,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM runtime_settings WHERE setting_key=?",Integer.class,JdbcCollectorHostMemory.key(f.f.node)));}
}
